
INSERT INTO public.blog_posts (slug, title, excerpt, content, category, meta_title, meta_description, keywords, published, published_at) VALUES
('walk-in-cooler-buying-guide-bahrain', 'دليل شراء غرف التبريد الووك إن في البحرين', 'كل ما تحتاج معرفته قبل شراء غرفة تبريد Walk-in Cooler لمطعمك أو محلك في البحرين: الأحجام والأسعار والصيانة.', E'# دليل شراء غرف التبريد Walk-in Cooler في البحرين\n\nغرفة التبريد من أهم استثمارات المطعم أو السوبرماركت. في هذا الدليل نستعرض:\n\n## الأحجام الشائعة\n- صغيرة 2×2 متر تناسب الكافيهات.\n- متوسطة 3×4 متر تناسب المطاعم.\n- كبيرة 5×6 متر فأكثر تناسب المخازن.\n\n## نصائح قبل الشراء\n- تحقق من ضاغط التبريد (Compressor) وحالة العزل.\n- اطلب تجربة تشغيل قبل الدفع.\n- تأكد من توفر قطع الغيار في البحرين.\n\n## الأسعار في البحرين\nتبدأ الغرف المستعملة من 800 دينار وتصل الجديدة إلى 4000 دينار حسب الحجم والمواصفات.\n\nللبيع والشراء تواصل مع حراج السعادة على 33982383.', 'restaurant', 'شراء غرف تبريد Walk-in Cooler في البحرين | حراج السعادة', 'دليل شامل لشراء غرف التبريد في البحرين: الأحجام والأسعار والصيانة. تواصل: 33982383.', 'غرف تبريد، walk-in cooler، معدات مطاعم البحرين، تبريد تجاري', true, now()),

('coffee-machine-buy-sell-bahrain', 'بيع وشراء ماكينات القهوة الاحترافية في البحرين', 'أفضل ماكينات القهوة للمقاهي في البحرين، الفرق بين La Marzocco و Nuova Simonelli، وأسعار المستعمل.', E'# ماكينات القهوة الاحترافية في البحرين\n\n## أفضل الماركات\n- La Marzocco (إيطاليا) — الأعلى جودة.\n- Nuova Simonelli — سعر/جودة ممتاز.\n- Rancilio و Astoria — خيارات اقتصادية.\n\n## المستعمل مقابل الجديد\nالماكينة المستعملة توفر 40-60% من السعر مع صيانة بسيطة. تحقق من:\n- الضغط (9 بار).\n- درجة حرارة البويلر.\n- حالة المضخة.\n\n## الأسعار في البحرين\nمستعمل: 400-1500 دينار. جديد: 1800-4500 دينار.\n\nنشتري ماكينات القهوة المستعملة مباشرة — 33982383.', 'restaurant', 'ماكينات قهوة احترافية للبيع في البحرين | حراج السعادة', 'دليل شراء وبيع ماكينات القهوة الاحترافية في البحرين، أفضل الماركات وأسعار المستعمل.', 'ماكينة قهوة، la marzocco، معدات كافيه، البحرين', true, now()),

('bahrain-restaurant-license-guide', 'خطوات استخراج ترخيص مطعم في البحرين 2026', 'دليل عملي لاستخراج ترخيص مطعم من وزارة الصناعة والتجارة وبلدية البحرين، مع تجهيز المعدات المطلوبة.', E'# استخراج ترخيص مطعم في البحرين\n\n## الخطوات الأساسية\n1. سجل تجاري من وزارة الصناعة والتجارة (سجلات.gov.bh).\n2. موافقة البلدية على الموقع.\n3. شهادة صحية للعمال.\n4. تجهيز المطبخ حسب اشتراطات الصحة.\n\n## المعدات الإلزامية\n- شفاط دخان مع فلتر.\n- ثلاجات ستانلس ستيل.\n- مغاسل ثلاثية.\n- سخان مياه.\n\n## التكلفة التقديرية\nالرسوم الحكومية 300-800 دينار. تجهيز المطبخ يبدأ من 8000 دينار.\n\nنساعدك بتجهيز مطعمك بالكامل — حراج السعادة 33982383.', 'restaurant', 'ترخيص مطعم في البحرين — دليل 2026 | حراج السعادة', 'خطوات استخراج ترخيص مطعم في البحرين، المعدات المطلوبة والتكاليف التقديرية.', 'ترخيص مطعم البحرين، تجهيز مطعم، سجل تجاري', true, now()),

('best-fryer-brands-bahrain', 'أفضل ماركات القلايات في البحرين ومقارنة الأسعار', 'مقارنة بين قلايات Henny Penny و Frymaster و Pitco مع أسعار المستعمل والجديد في البحرين.', E'# أفضل قلايات المطاعم في البحرين\n\n## الماركات الرائدة\n- **Henny Penny**: الأشهر لقلي الدجاج تحت الضغط.\n- **Frymaster**: ماركة أمريكية موثوقة.\n- **Pitco**: سعر/أداء ممتاز.\n\n## معايير الاختيار\n- سعة الزيت (18-25 لتر للتجاري).\n- نظام الفلترة.\n- الطاقة (غاز أم كهرباء).\n\n## الأسعار في البحرين\nقلاية مستعملة: 300-1200 دينار. جديدة: 900-3500 دينار.\n\nنبيع ونشتري القلايات — حراج السعادة 33982383.', 'restaurant', 'قلايات مطاعم للبيع في البحرين | حراج السعادة', 'مقارنة أفضل ماركات القلايات في البحرين Henny Penny و Frymaster و Pitco مع الأسعار.', 'قلاية، henny penny، معدات مطعم، البحرين', true, now()),

('used-office-furniture-manama', 'أثاث مكتبي مستعمل في المنامة — دليل الشراء الذكي', 'كيف تجهز مكتبك بأثاث مستعمل عالي الجودة في المنامة وتوفر حتى 60% من التكلفة.', E'# أثاث مكتبي مستعمل في المنامة\n\n## القطع الأساسية\n- مكاتب تنفيذية.\n- كراسي أرغونومية.\n- خزائن ملفات.\n- طاولات اجتماعات.\n\n## نصائح الشراء\n- افحص القوائم والدرجات المعدنية.\n- جرب آلية الرفع في الكراسي.\n- اطلب فاتورة بسيطة للضمان.\n\n## أفضل الماركات\nHerman Miller, Steelcase, Haworth — تدوم 15+ سنة حتى مستعملة.\n\nتصفح إعلانات الأثاث المكتبي في حراج السعادة.', 'furniture', 'أثاث مكتبي مستعمل في المنامة | حراج السعادة', 'دليل شراء الأثاث المكتبي المستعمل في المنامة والبحرين بأفضل الأسعار.', 'أثاث مكتبي، مكاتب مستعملة، المنامة، البحرين', true, now()),

('home-appliances-bahrain-guide', 'أجهزة كهربائية منزلية مستعملة في البحرين — دليل 2026', 'ثلاجات وغسالات ومكيفات مستعملة بضمان في البحرين. كيف تختار الأفضل وتتجنب الخدع.', E'# الأجهزة الكهربائية المستعملة في البحرين\n\n## الثلاجات\n- Samsung و LG الأكثر توفراً لقطع الغيار.\n- افحص مبرد الفريزر وباب الإحكام.\n\n## الغسالات\n- Bosch و Siemens الأطول عمراً.\n- تحقق من محرك Direct Drive.\n\n## المكيفات\n- Split أفضل لغرف النوم.\n- تأكد من عدم تسرب الفريون.\n\n## الأسعار\nثلاجة مستعملة: 60-250 دينار. غسالة: 50-180. مكيف سبليت: 80-200.\n\nحراج السعادة يوفر تشكيلة واسعة.', 'electronics', 'أجهزة كهربائية مستعملة في البحرين | حراج السعادة', 'ثلاجات وغسالات ومكيفات مستعملة في البحرين بأفضل الأسعار مع نصائح الشراء.', 'ثلاجة مستعملة، غسالة، مكيف، البحرين', true, now()),

('shawarma-machine-buying-guide', 'دليل شراء مكائن الشاورما في البحرين', 'ماكينات شاورما غاز أم كهرباء؟ سعات مختلفة وأسعار المستعمل والجديد في السوق البحريني.', E'# ماكينات الشاورما في البحرين\n\n## الأنواع\n- **غاز**: أسرع تسخيناً، تكلفة تشغيل أقل.\n- **كهربا��**: نظيفة، مناسبة للمولات.\n\n## السعات\n- 3 شعلات: للمطاعم الصغيرة.\n- 4-5 شعلات: للمطاعم المتوسطة.\n- 6+ شعلات: للسلاسل الكبيرة.\n\n## الأسعار\nمستعملة: 150-500 دينار. جديدة: 400-1200 دينار.\n\nنشتري ونبيع مكائن الشاورما — 33982383.', 'restaurant', 'ماكينات شاورما للبيع في البحرين | حراج السعادة', 'دليل شامل لشراء ماكينات الشاورما في البحرين — غاز أم كهرباء، السعات والأسعار.', 'ماكينة شاورما، معدات مطعم، البحرين، شاورما غاز', true, now()),

('sell-fast-tips-haraj', '10 نصائح لبيع إعلانك في حراج السعادة خلال 24 ساعة', 'تقنيات مثبتة لتسريع بيع منتجاتك على حراج السعادة: التصوير، العنوان، السعر، والتواصل.', E'# كيف تبيع خلال 24 ساعة\n\n## 1. صور احترافية\nاستخدم إضاءة طبيعية وخلفية نظيفة. 5 صور من زوايا مختلفة.\n\n## 2. عنوان واضح\nاذكر الماركة والموديل والحالة. مثال: "ثلاجة سامسونج 500 لتر — استعمال 6 أشهر".\n\n## 3. سعر تنافسي\nابحث عن إعلانات مشابهة وضع سعرك 5-10% أقل للبيع السريع.\n\n## 4. وصف كامل\nذكر السبب، الاستخدام، أي عيوب. الشفافية تبني الثقة.\n\n## 5. رد سريع\nراقب الرسائل ورد خلال ساعة.\n\n## 6-10\n- روّج على واتساب.\n- اجعل التسليم مرناً.\n- استخدم خاصية "إعلان مميز".\n- كن مستعداً للمساومة الخفيفة.\n- اطلب تقييماً بعد البيع.', 'general', '10 نصائح لبيع سريع في حراج السعادة', 'أسرار بيع إعلاناتك خلال 24 ساعة على حراج السعادة البحرين.', 'بيع سريع، حراج البحرين، نصائح بيع', true, now()),

('ice-machine-buying-bahrain', 'دليل شراء ماكينات الثلج للمطاعم والفنادق في البحرين', 'أنواع ماكينات الثلج (Cube, Flake, Nugget) وكيف تختار السعة المناسبة لمشروعك.', E'# ماكينات الثلج في البحرين\n\n## الأنواع\n- **Cube Ice**: للمشروبات الباردة والبارات.\n- **Flake Ice**: لعرض الأسماك والسلطات.\n- **Nugget Ice**: للعصائر ومحلات الشاورما.\n\n## السعات\n- 50-100 كجم/يوم: للكافيهات.\n- 150-300 كجم/يوم: للمطاعم.\n- 500+ كجم/يوم: للفنادق والمصانع.\n\n## الماركات الموصى بها\nHoshizaki, Manitowoc, Scotsman.\n\n## الأسعار\nمستعمل: 400-2000 دينار. جديد: 1200-6000 دينار.\n\nحراج السعادة — 33982383.', 'restaurant', 'ماكينات ثلج للبيع في البحرين | حراج السعادة', 'دليل شراء ماكينات الثلج للمطاعم في البحرين — الأنواع والسعات والأسعار.', 'ماكينة ثلج، ice machine، معدات مطعم، البحرين', true, now()),

('bahrain-marketplace-safety-2026', 'أمان التسوق في حراج البحرين 2026 — دليل حماية المشتري والبائع', 'إرشادات حديثة لحماية نفسك من الاحتيال عند البيع أو الشراء في حراج البحرين الإلكتروني.', E'# أمان التعاملات في حراج البحرين 2026\n\n## علامات الاحتيال\n- طلب دفع مقدم قبل رؤية المنتج.\n- بائع خارج البحرين يطلب شحن دولي.\n- سعر أقل بكثير من السوق.\n- ضغط لإتمام الصفقة بسرعة.\n\n## قواعد الأمان\n1. قابل البائع في مكان عام مضاء.\n2. افحص المنتج قبل الدفع.\n3. ادفع نقداً أو تحويل بنكي موثق.\n4. لا تشارك OTP أو رمز التحقق أبداً.\n5. احتفظ بسجل المحادثات.\n\n## ما يفعله حراج السعادة\n- تحقق من هوية البائعين المميزين.\n- نظام تقييم شفاف.\n- دعم فوري 33982383.', 'general', 'أمان التسوق في حراج البحرين 2026 | حراج السعادة', 'دليل حماية المشتري والبائع من الاحتيال في مواقع الحراج الإلكتروني في البحرين.', 'أمان الحراج، احتيال إلكتروني، البحرين، حراج آمن', true, now());
